  ])->save();

  \Drupal::service('entity_display.repository')
    ->getFormDisplay('node', $this->type)
    ->setComponent($this->fieldName)
    ->save();

  $this->adminPath = 'admin/structure/types/manage/' . $this->type . '/fields/node.' . $this->type . '.' . $this->fieldName;
}

