  if (!$exclude_locked_roles) {
    if ($this->isAuthenticated()) {
      $roles[] = RoleInterface::AUTHENTICATED_ID;
    }
    else {
      $roles[] = RoleInterface::ANONYMOUS_ID;
    }
  }

  foreach ($this->get('roles') as $role) {
    if ($role->target_id) {
      $roles[] = $role->target_id;
    }
  }

  return $roles;
}

